{"code": "// Batch 1a: 加载 6 个必需技能（并行读取）
const skills = [
  "godot-ai-orchestration",
  "godot-2d-movement",
  "godot-physics",
  "godot-ui-control",
  "godot-animation",
  "godot-signals-groups",
];
const results = await Promise.all(skills.map(async (name) => {
  try {
    const r = await tools.skill({ name });
    return { name, ok: true, len: r.content.length, head: r.content.slice(0, 400) };
  } catch (e) {
    return { name, ok: false, err: String(e).slice(0, 300) };
  }
}));
return results.map(r => `${r.name}: ${r.ok ? `OK (${r.len} chars)` : "FAIL " + r.err}`).join("\n---\n") + "\n\n--- heads ---\n" + results.filter(r=>r.ok).map(r => `${r.name}:\n${r.head}`).join("\n\n");", "description": "Load 6 required Godot skills in parallel"}

{"code": "// Batch 1b: 会话发现 + 编辑器状态 + 项目信息（并行只读）
const [sessions, state, projInfo] = await Promise.all([
  tools["mcp__godot-ai__session_manage"]({ op: "list" }).catch(e => ({ error: String(e).slice(0, 500) })),
  tools["mcp__godot-ai__editor_state"]({}).catch(e => ({ error: String(e).slice(0, 500) })),
  tools["mcp__godot-ai__project_manage"]({ op: "settings_get", params: { key: "application/config/name" } }).catch(e => ({ error: String(e).slice(0, 500) })),
]);
return JSON.stringify({ sessions, state, projInfo }, null, 1);", "description": "Discover editor sessions, state, and project name"}

