{"code": "// 批次2-配置A：InputMap actions
// 先确保 action 存在，再绑定事件
const ops = [
  { op: "ensure_action", params: { action: "move_left" } },
  { op: "ensure_action", params: { action: "move_right" } },
  { op: "ensure_action", params: { action: "jump" } },
  { op: "ensure_action", params: { action: "restart" } },
];
const results = [];
for (const o of ops) {
  const r = await tools["mcp__godot-ai__input_map_manage"](o).catch(e => ({ error: String(e).slice(0, 300) }));
  results.push(r);
}
// 绑定事件
const binds = [
  { action: "move_left", event_type: "key", keycode: "A" },
  { action: "move_left", event_type: "key", keycode: "Left" },
  { action: "move_right", event_type: "key", keycode: "D" },
  { action: "move_right", event_type: "key", keycode: "Right" },
  { action: "jump", event_type: "key", keycode: "W" },
  { action: "jump", event_type: "key", keycode: "Space" },
  { action: "jump", event_type: "key", keycode: "Up" },
  { action: "restart", event_type: "key", keycode: "R" },
];
const bindResults = [];
for (const b of binds) {
  const r = await tools["mcp__godot-ai__input_map_manage"]({ op: "ensure_binding", params: b }).catch(e => ({ error: String(e).slice(0, 200) }));
  bindResults.push({ b, r: r.structuredContent || r });
}
return JSON.stringify({ actions: results.map(r => r.structuredContent || r), binds: bindResults }, null, 1).slice(0, 5000);", "description": "Create and bind InputMap actions for game"}

