  let src = 0;
  for (let y = 0; y < height; y++) {
    const filter = raw[src++];
    const row = raw.subarray(src, src + stride);
    src += stride;
    // 简化：只处理 filter 0/1/2 (None/Sub/Up)，Godot 截图通常用 filter 0 或 1
    for (let x = 0; x < width; x++) {
